import{f as t,o as n,c as a,ar as o}from"./chunks/framework.HWAOx3Ef.js";const u=JSON.parse('{"title":"Naming Convention für Frontend Elemente","description":"","frontmatter":{},"headers":[],"relativePath":"technik/naming_conventions/frontend.md","filePath":"technik/naming_conventions/frontend.md"}'),r={name:"technik/naming_conventions/frontend.md"};function s(i,e,l,d,c,p){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="naming-convention-fur-frontend-elemente" tabindex="-1">Naming Convention für Frontend Elemente <a class="header-anchor" href="#naming-convention-fur-frontend-elemente" aria-label="Permalink to &quot;Naming Convention für Frontend Elemente&quot;">​</a></h1><p>Bitte den <a href="https://vuejs.org/style-guide/" target="_blank" rel="noreferrer">StyleGuide</a> beachten.</p><ul><li>Dateinamen sind in [c|C]amelCase</li><li>Definitionen von Properties, Events und lokalen Variablen in camelCase</li><li>Element-Attribute in Kebab-Case</li></ul><p>Die Benennung erfolgt grundsätzlich auf Englisch, mit Ausnahme von Fachbegriffen welche auf Deutsch verwendet werden.</p><h2 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h2><p><code>[UWB|BWB]&lt;Domain&gt;[&lt;Funktion&gt;]View.vue</code></p><p>Der Prefix <code>UWB</code> oder <code>BWB</code> ist zu setzen wenn diese View nur für eine bestimmte Wahlbezirksart gedacht ist. Erfolgt innerhalb der View eine Unterscheidung welche Subkomponenten angezeigt werden, oder ist die View unabhängig von der Wahlbezirksart, ist kein Prefix zu vergeben.</p><h3 id="beispiel" tabindex="-1">Beispiel <a class="header-anchor" href="#beispiel" aria-label="Permalink to &quot;Beispiel&quot;">​</a></h3><p><code>WahlvorstandView.vue</code> ... eine View für den Wahlvorstand, die für alle Wahlbezirksarten gedacht ist<br><code>UWBWaehlerverzeichnisView.vue</code> ... eine View die nur bei der Wahlbezirksart <code>UWB</code> angezeigt werden soll</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><h3 id="basiskomponenten" tabindex="-1">Basiskomponenten <a class="header-anchor" href="#basiskomponenten" aria-label="Permalink to &quot;Basiskomponenten&quot;">​</a></h3><p><code>Base&lt;Type&gt;[&lt;Domain&gt;]&lt;Funktion&gt;.vue</code></p><p><strong>Beispiele:</strong></p><p><code>BaseButtonRefresh.vue</code> ... Allgemeiner Button zur Aktualisierung</p><p><code>BaseButtonSave.vue</code> ... Allgemeiner Button zum Speichern</p><p><code>BaseWahlvorstandMitgliedCard.vue</code> ... V-Card zur Darstellung eines Wahlvorstandsmitgliedes</p><h3 id="single-instance-komponenten" tabindex="-1">Single-Instance-Komponenten <a class="header-anchor" href="#single-instance-komponenten" aria-label="Permalink to &quot;Single-Instance-Komponenten&quot;">​</a></h3><p><code>The[&lt;Domain&gt;]&lt;Funktion&gt;&lt;Type&gt;.vue</code></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Die Bezeichnung stammt aus einem älteren <a href="https://v2.vuejs.org/v2/style-guide/#Single-instance-component-names-strongly-recommended" target="_blank" rel="noreferrer">StyleGuide</a></p></div><p><strong>Beispiele:</strong></p><p><code>TheWahlvorstandLastSendDiv.vue</code> ... Wahlvorstandskomponente welche die Uhrzeit der letzten Übermittlung darstellt</p><p><code>TheWahlvorstandMitgliederTable.vue</code> ... Wahlvorstandskomponente welche Mitglieder des Wahlvorstandes als Tabelle anzeigt</p><h2 id="stores" tabindex="-1">Stores <a class="header-anchor" href="#stores" aria-label="Permalink to &quot;Stores&quot;">​</a></h2><p><code>&lt;domain&gt;Store.ts</code></p><p><strong>Beispiel:</strong></p><p><code>wahlvorstandStore.ts</code> ... Store für den Wahlvorstand</p><h2 id="composables" tabindex="-1">Composables <a class="header-anchor" href="#composables" aria-label="Permalink to &quot;Composables&quot;">​</a></h2><h3 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h3><p><code>[&lt;domain&gt;]Rules.ts</code></p><p>Für eine Modularisierung ist es möglich spezielle Rules einer Domain zuzuordnen.</p><h3 id="formatter" tabindex="-1">Formatter <a class="header-anchor" href="#formatter" aria-label="Permalink to &quot;Formatter&quot;">​</a></h3><p><code>&lt;domain|typ&gt;Formatter.ts</code></p><p>Formatter gehören zu einem Datentyp oder einer Domain.</p><p><strong>Beispiel:</strong></p><p><code>textFormatter.ts</code> ... Formartierungsfunktionen für Text</p><p><code>dateTimeFormatter.ts</code> ... Formatierungsfunktionen für Date</p><h3 id="utils" tabindex="-1">Utils <a class="header-anchor" href="#utils" aria-label="Permalink to &quot;Utils&quot;">​</a></h3><p><code>&lt;komponentenName&gt;Utils.ts</code></p><p><strong>Beispiel:</strong></p><p><code>theBeschlussfassungStartenDialogUtils.ts</code> ... ist das Utils-Composable für die Komponente <code>TheBeschlussfassungStartenDialog</code></p><h3 id="storemodule" tabindex="-1">StoreModule <a class="header-anchor" href="#storemodule" aria-label="Permalink to &quot;StoreModule&quot;">​</a></h3><p><code>&lt;domain&gt;[&lt;Funktion&gt;]StoreModule.ts</code></p><p><strong>Beispiel:</strong></p><p><code>briefwahlGetterStoreModule.ts</code> ... kapselt Funktionalität zu einem Thema eines Stores</p><h3 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h3><p><code>&lt;domain&gt;[&lt;Funktion&gt;]State.ts</code></p><p><strong>Beispiel:</strong></p><p><code>stimmzettelWorkflowStatusState.ts</code> ... Verwaltet einen konkreten WorkflowStatus (Daten und Loading) für einen konkreten Wahlbezirk</p><h3 id="mapper" tabindex="-1">Mapper <a class="header-anchor" href="#mapper" aria-label="Permalink to &quot;Mapper&quot;">​</a></h3><p><code>&lt;domain&gt;Mapper.ts</code></p><p><strong>Beispiel:</strong></p><p><code>wahlvorstandMapper.ts</code> ... enthält Mappingfunktionen zum Wahlvorstand</p><h3 id="fetchservice" tabindex="-1">FetchService <a class="header-anchor" href="#fetchservice" aria-label="Permalink to &quot;FetchService&quot;">​</a></h3><p><code>&lt;domain&gt;FetchService.ts</code></p><p><strong>Beispiel:</strong></p><p><code>wahlvorstandFetchService.ts</code> ... stellt Funktionen bereit, um Daten des Wahlvorstandes aus dem Backend abzurufen</p><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><p><code>&lt;typ&gt;Tools.ts</code></p><p><strong>Beispiel:</strong></p><p><code>wahlvorstandsMitgliedTools.ts</code> ... stellt Funktionen rund um den Datentyp bereit, wie z.B. die Erstellung eines fachlich leeren Objektes</p><h3 id="manager" tabindex="-1">Manager <a class="header-anchor" href="#manager" aria-label="Permalink to &quot;Manager&quot;">​</a></h3><p><code>&lt;topic&gt;Manager.ts</code></p><p><strong>Beispiel:</strong></p><p><code>requestStrategyManager.ts</code> ... kapselt die diversen RequestStrategien und entscheidet im Rahmen der Verarbeitung, welche Strategy anzuwenden ist</p><h3 id="service" tabindex="-1">Service <a class="header-anchor" href="#service" aria-label="Permalink to &quot;Service&quot;">​</a></h3><p><code>&lt;topic&gt;Service.ts</code></p><p><strong>Beispiel:</strong></p><p><code>loggingService.ts</code> ... stellt Funktionen zu einem Thema bereit, dass sonst zu keinem Typ Composable passt</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><p><code>&lt;interface&gt;.ts</code></p><p><strong>Beispiel:</strong></p><p><code>Wahlvorstand.ts</code> ... enthält das Interface <code>Wahlvorstand</code> und eine Hilfsklasse die das Interface implementiert</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>Die Tests liegen im <code>tests</code>-Ordner, welcher der Aufbaustruktur des <code>src</code>-Ordners folgt.</p><p><code>&lt;Testgegenstand ohne Dateiendung&gt;.spec.ts</code></p><p><strong>Beispiel:</strong></p><p><code>TheWahlvorstandMitgliederTable.spec.ts</code> ... Tests zu <code>TheWahlvorstandMitgliederTable.vue</code></p><p><code>wahlvorstandStore.spec.ts</code> ... Tests zu <code>wahlvorstandStore.ts</code></p><h2 id="storybook-stories" tabindex="-1">Storybook Stories <a class="header-anchor" href="#storybook-stories" aria-label="Permalink to &quot;Storybook Stories&quot;">​</a></h2><p><code>&lt;Storybookgegenstand ohne Dateiendung&gt;.stories.ts</code></p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Stories zu Komponenten, die den Store verwenden, haben auf der Übersichtsseite (<code>docs</code>) alle denselben Zustand. Der Zustand für alle Komponenten entsprecht dem Zustand im Store mit der letzten Story.</p></div><p><strong>Beispiel:</strong></p><p><code>BaseButtonRefresh.stories.ts</code> ... Stories zu <code>BaseButtonRefresh.vue</code></p><h2 id="testattribut" tabindex="-1">Testattribut <a class="header-anchor" href="#testattribut" aria-label="Permalink to &quot;Testattribut&quot;">​</a></h2><p>Damit Elemente leichter für Tests zugänglich sind, sollen sie ein Attribut für Tests bekommen. Der Name des Attributes ist <a href="https://docs.cypress.io/app/core-concepts/best-practices#Selecting-Elements" target="_blank" rel="noreferrer"><code>data-test</code></a>.</p><p>Bei dem Wert handelt es sich <strong>nicht</strong> um eine ID.</p><h2 id="eventhandlingmethoden" tabindex="-1">Eventhandlingmethoden <a class="header-anchor" href="#eventhandlingmethoden" aria-label="Permalink to &quot;Eventhandlingmethoden&quot;">​</a></h2><p><code>on&lt;Data&gt;&lt;Event&gt;</code></p><p><strong>Beispiel:</strong></p><p><code>onAnwesenheitChanged($event, mitglied)</code> ... Eventhandler, wenn sich die Anwesenheit geändert hat</p>',90)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
